export interface MCPViewServer {
  name: string;
  known: boolean;
  off?: boolean;
  views: MCPViewInfo[];
}

export interface MCPViewInfo {
  id: string;
  tool: string;
  title: string;
  description?: string;
  params: MCPViewParam[];
  fields: MCPViewField[];
  layout: "table" | "list" | "card" | "detail" | "text" | "json";
  typed?: "schema" | "learned";
  run?: boolean;
  why?: string;
  resources?: MCPViewChoice[];
}

export interface MCPViewParam {
  id: string;
  label: string;
  kind: "string" | "int" | "number" | "bool" | "enum" | "uri";
  enum?: string[];
  required?: boolean;
  hint?: string;
}

export interface MCPViewField {
  id: string;
  label: string;
  kind: "text" | "num" | "time" | "bool" | "link" | "json";
}

export interface MCPViewChoice {
  uri: string;
  name: string;
  template?: boolean;
  vars?: string[];
}

export interface MCPViewData {
  view: string;
  title: string;
  layout: "table" | "list" | "card" | "detail" | "text" | "json" | "status";
  block?: Block;
  raw: string;
  truncated?: boolean;
  error?: boolean;
  ask?: string;
}

export interface ViewRunResult {
  block: Block;
  live?: string;
}

export interface ViewCatalog {
  features: string[];
  views: ViewDef[];
}

export interface ViewDef {
  id: string;
  feature: string;
  title: string;
  source: ViewSource;
  params?: ViewParam[];
  fields: ViewField[];
  layouts: string[];
  default: ViewSpec;
  actions?: BlockAction[];
  role: "viewer" | "controller";
  live?: boolean;
  refresh?: number;
}

export interface ViewSource {
  topic?: string;
  op?: string;
  tool?: string;
  mcp_server?: string;
  mcp_tool?: string;
}

export interface ViewParam {
  id: string;
  label: string;
  kind: "ws" | "string" | "int" | "enum" | "path" | "table" | "conn" | "number_pr" | "uri";
  enum?: string[];
  required?: boolean;
}

export interface ViewField {
  id: string;
  label: string;
  kind: "text" | "num" | "time" | "state" | "path" | "link" | "bool" | "cost" | "md";
  sortable?: boolean;
  filterable?: boolean;
  default?: boolean;
}

export interface ProjectClosed {
  ws: string;
}

export type ClientMsg = Bye | Hello | Ping | Req | Sub | Unsub;
export type ServerMsg = Delta | ErrMsg | Event | Meta | Pong | Res | Resync | ServerBye | Snap;

